def buscar(lista, x):
    left, right = 0, len(lista) - 1
    while left <= right:
        mid = (left + right) // 2
        if lista[mid] == x:
            return mid
        elif lista[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    return -1

