def from_roman(s: str) -> int:
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i, ch in enumerate(s):
        if i + 1 < len(s) and roman[ch] < roman[s[i + 1]]:
            total -= roman[ch]
        else:
            total += roman[ch]
    return total

