def fusionar(intervalos):
    if not intervalos:
        return []
    intervalos.sort(key=lambda x: x[0])
    fusion = [intervalos[0]]
    for start, end in intervalos[1:]:
        last_start, last_end = fusion[-1]
        if start <= last_end:
            fusion[-1] = (last_start, max(last_end, end))
        else:
            fusion.append((start, end))
    return fusion

def balanceado(cadena):
    pila = []
    pares = {
        ')': '(',
        '}': '{',
        ']': '['
    }
    for char in cadena:
        if char in pares.values():
            pila.append(char)
        elif char in pares:
            if not pila or pila[-1] != pares[char]:
                return False
            pila.pop()
    return len(pila) == 0

